# PowerPC instruction test executor.
#
# Runs every test case of 'cases' (generated by tools/ppc-testgen.py): loads
# the case's register and scratch memory state, executes the single test
# instruction and writes the resulting state to stdout. The same binary runs
# under qemu-ppc (the oracle) and under the emulator's CPU core
# (tests/linux/ppc-exec.cpp); their outputs must match.
#
# Case record (384 bytes):            Result record (384 bytes):
#   0 insn                               0 cr
#   4 cr                                 4 xer
#   8 xer                                8 fpscr
#  12 fpscr                             12 ctr
#  16 ctr                               16 lr
#  20 lr                                20 r3..r12 (40 bytes)
#  24 r3..r12 (40 bytes)                60 unused
#  64 f0..f31 (256 bytes)               64 f0..f31
# 320 scratch memory (64 bytes)        320 scratch memory
#
# Only r3-r12, f0-f31, CR, XER, FPSCR, CTR and LR belong to the test; the
# executor keeps its state in r20-r31.

	.set CASE_SIZE, 384
	.set BATCH, 64

	.section .text
	.globl _start
_start:
	lis	%r20, cases@ha
	addi	%r20, %r20, cases@l
	lis	%r21, case_count@ha
	lwz	%r21, case_count@l(%r21)
	lis	%r24, scratch@ha
	addi	%r24, %r24, scratch@l
	lis	%r25, test_buffer@ha
	addi	%r25, %r25, test_buffer@l

	# enable the FPU for the emulator run (qemu user mode has it on)
batch:
	lis	%r22, results@ha
	addi	%r22, %r22, results@l
	li	%r23, 0			# cases in this batch

next_case:
	cmpwi	%r21, 0
	beq	flush

	# scratch memory
	li	%r26, 0
1:	addi	%r27, %r26, 320
	lwzx	%r28, %r20, %r27
	stwx	%r28, %r24, %r26
	addi	%r26, %r26, 4
	cmpwi	%r26, 64
	blt	1b

	# patch the test instruction
	lwz	%r28, 0(%r20)
	stw	%r28, 0(%r25)
	dcbst	0, %r25
	sync
	icbi	0, %r25
	isync

	# FPSCR (through f0), then the FPRs
	lwz	%r28, 12(%r20)
	stw	%r28, 4(%r24)		# scratch is reloaded for every case
	lfd	%f0, 0(%r24)
	mtfsf	0xff, %f0
	# restore the scratch word we used
	lwz	%r28, 324(%r20)
	stw	%r28, 4(%r24)
	lfd	%f0, 64(%r20)
	lfd	%f1, 72(%r20)
	lfd	%f2, 80(%r20)
	lfd	%f3, 88(%r20)
	lfd	%f4, 96(%r20)
	lfd	%f5, 104(%r20)
	lfd	%f6, 112(%r20)
	lfd	%f7, 120(%r20)
	lfd	%f8, 128(%r20)
	lfd	%f9, 136(%r20)
	lfd	%f10, 144(%r20)
	lfd	%f11, 152(%r20)
	lfd	%f12, 160(%r20)
	lfd	%f13, 168(%r20)
	lfd	%f14, 176(%r20)
	lfd	%f15, 184(%r20)
	lfd	%f16, 192(%r20)
	lfd	%f17, 200(%r20)
	lfd	%f18, 208(%r20)
	lfd	%f19, 216(%r20)
	lfd	%f20, 224(%r20)
	lfd	%f21, 232(%r20)
	lfd	%f22, 240(%r20)
	lfd	%f23, 248(%r20)
	lfd	%f24, 256(%r20)
	lfd	%f25, 264(%r20)
	lfd	%f26, 272(%r20)
	lfd	%f27, 280(%r20)
	lfd	%f28, 288(%r20)
	lfd	%f29, 296(%r20)
	lfd	%f30, 304(%r20)
	lfd	%f31, 312(%r20)

	lwz	%r28, 4(%r20)
	mtcrf	0xff, %r28
	lwz	%r28, 8(%r20)
	mtxer	%r28
	lwz	%r28, 16(%r20)
	mtctr	%r28
	lwz	%r28, 20(%r20)
	mtlr	%r28
	lwz	%r3, 24(%r20)
	lwz	%r4, 28(%r20)
	lwz	%r5, 32(%r20)
	lwz	%r6, 36(%r20)
	lwz	%r7, 40(%r20)
	lwz	%r8, 44(%r20)
	lwz	%r9, 48(%r20)
	lwz	%r10, 52(%r20)
	lwz	%r11, 56(%r20)
	lwz	%r12, 60(%r20)
	b	test_buffer

	.globl test_return
test_return:
	stw	%r3, 20(%r22)
	stw	%r4, 24(%r22)
	stw	%r5, 28(%r22)
	stw	%r6, 32(%r22)
	stw	%r7, 36(%r22)
	stw	%r8, 40(%r22)
	stw	%r9, 44(%r22)
	stw	%r10, 48(%r22)
	stw	%r11, 52(%r22)
	stw	%r12, 56(%r22)
	mfcr	%r28
	stw	%r28, 0(%r22)
	mfxer	%r28
	stw	%r28, 4(%r22)
	mfctr	%r28
	stw	%r28, 12(%r22)
	mflr	%r28
	stw	%r28, 16(%r22)
	li	%r28, 0
	stw	%r28, 60(%r22)
	stfd	%f0, 64(%r22)
	stfd	%f1, 72(%r22)
	stfd	%f2, 80(%r22)
	stfd	%f3, 88(%r22)
	stfd	%f4, 96(%r22)
	stfd	%f5, 104(%r22)
	stfd	%f6, 112(%r22)
	stfd	%f7, 120(%r22)
	stfd	%f8, 128(%r22)
	stfd	%f9, 136(%r22)
	stfd	%f10, 144(%r22)
	stfd	%f11, 152(%r22)
	stfd	%f12, 160(%r22)
	stfd	%f13, 168(%r22)
	stfd	%f14, 176(%r22)
	stfd	%f15, 184(%r22)
	stfd	%f16, 192(%r22)
	stfd	%f17, 200(%r22)
	stfd	%f18, 208(%r22)
	stfd	%f19, 216(%r22)
	stfd	%f20, 224(%r22)
	stfd	%f21, 232(%r22)
	stfd	%f22, 240(%r22)
	stfd	%f23, 248(%r22)
	stfd	%f24, 256(%r22)
	stfd	%f25, 264(%r22)
	stfd	%f26, 272(%r22)
	stfd	%f27, 280(%r22)
	stfd	%f28, 288(%r22)
	stfd	%f29, 296(%r22)
	stfd	%f30, 304(%r22)
	stfd	%f31, 312(%r22)
	# copy the scratch memory before using it for mffs
	li	%r26, 0
1:	lwzx	%r28, %r24, %r26
	addi	%r27, %r26, 320
	stwx	%r28, %r22, %r27
	addi	%r26, %r26, 4
	cmpwi	%r26, 64
	blt	1b
	mffs	%f0
	stfd	%f0, 0(%r24)
	lwz	%r28, 4(%r24)
	stw	%r28, 8(%r22)

	addi	%r20, %r20, CASE_SIZE
	addi	%r22, %r22, CASE_SIZE
	addi	%r21, %r21, -1
	addi	%r23, %r23, 1
	cmpwi	%r23, BATCH
	blt	next_case

flush:
	cmpwi	%r23, 0
	beq	done_flush
	li	%r0, 4			# write(1, results, count * CASE_SIZE)
	li	%r3, 1
	lis	%r4, results@ha
	addi	%r4, %r4, results@l
	mulli	%r5, %r23, CASE_SIZE
	sc
done_flush:
	cmpwi	%r21, 0
	bne	batch
	li	%r0, 1			# exit(0)
	li	%r3, 0
	sc

	.section .testcode, "awx"
	.align 4
	.globl test_buffer
test_buffer:
	.long 0
	b	test_return

	.section .bss
	.align 6
	.globl scratch
scratch:
	.space 64
	.align 4
results:
	.space CASE_SIZE * BATCH
